from metpy.io.text import _decode_coords

def test_decode_coords():
    test_cases = [
        ('4731193', (-119.3, 47.3)),
        ('-3880854', (-85.4, -38.8)),
        ('4711', (-11.0, 47.0)),
        ('47119', (-119.0, 47.0)),
        ('-4711', (-11.0, -47.0)),
    ]

    for coords, expected in test_cases:
        result = _decode_coords(coords)
        print(f"Coords: {coords}, Expected: {expected}, Result: {result}")
        assert result == expected

if __name__ == "__main__":
    try:
        test_decode_coords()
        print("All tests passed!")
    except AssertionError as e:
        print(f"Test failed!")
        raise e
